CREATE TABLE combo_offers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,badge VARCHAR(100) NULL,short_description VARCHAR(500) NULL,description TEXT NULL,banner_image VARCHAR(500) NULL,regular_price DECIMAL(12,2) NOT NULL DEFAULT 0,discount_percent DECIMAL(6,2) NOT NULL DEFAULT 0,combo_price DECIMAL(12,2) NOT NULL DEFAULT 0,layout_slot ENUM('large','wide','square') NOT NULL DEFAULT 'square',cta_text VARCHAR(80) NOT NULL DEFAULT 'View Offer',show_title TINYINT(1) NOT NULL DEFAULT 1,show_badge TINYINT(1) NOT NULL DEFAULT 1,show_cta TINYINT(1) NOT NULL DEFAULT 1,show_short_description TINYINT(1) NOT NULL DEFAULT 1,show_description TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,show_on_home TINYINT(1) NOT NULL DEFAULT 1,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL ON UPDATE CURRENT_TIMESTAMP,KEY idx_combo_home (is_active,show_on_home,sort_order));
CREATE TABLE combo_offer_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,combo_offer_id INT UNSIGNED NOT NULL,product_id INT UNSIGNED NOT NULL,quantity INT NOT NULL DEFAULT 1,regular_price DECIMAL(12,2) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_combo_items (combo_offer_id,sort_order),CONSTRAINT fk_combo_items_offer FOREIGN KEY (combo_offer_id) REFERENCES combo_offers(id) ON DELETE CASCADE);

CREATE TABLE combo_offer_custom_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,combo_offer_id INT UNSIGNED NOT NULL,item_name VARCHAR(180) NOT NULL,quantity INT NOT NULL DEFAULT 1,item_price DECIMAL(12,2) NOT NULL DEFAULT 0,thumbnail_path VARCHAR(500) NULL,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_combo_custom_items (combo_offer_id,sort_order),CONSTRAINT fk_combo_custom_offer FOREIGN KEY (combo_offer_id) REFERENCES combo_offers(id) ON DELETE CASCADE);
